const COST_RE = /^[0-9]+$/

export class ParseError extends Error {}

function fail(message) {
  throw new ParseError(message)
}

function checkName(name, lineNo) {
  if (!NAME_RE.test(name)) fail(`error: line ${lineNo}: invalid task name ${name}`)
}

/**
 * Parses the build graph description read from standard input.
 *
 * Returns { tasks: Map<name, cost>, deps: Map<name, Set<name>> }.
 * Throws ParseError with the full "error: ..." message on any malformed
 * directive, duplicate declaration, or reference to an undeclared task.
 */
export function parseGraph(input) {
  const lines = input.split('\n')
  if (lines.length > 0 && lines[lines.length - 1] === '') lines.pop()

  const tasks = new Map()
  const deps = new Map()
  const depUsages = []

  for (let i = 0; i < lines.length; i++) {
    const lineNo = i + 1
    const trimmed = lines[i].trim()
    if (trimmed === '' || trimmed.startsWith('#')) continue
    const words = trimmed.split(/\s+/)
    const directive = words[0]

    if (directive === 'task') {
      if (words.length !== 3) fail(`error: line ${lineNo}: expected task <name> <cost>`)
      const [, name, costStr] = words
      checkName(name, lineNo)
      if (!COST_RE.test(costStr)) fail(`error: line ${lineNo}: cost must be a non-negative integer`)
      if (tasks.has(name)) fail(`error: line ${lineNo}: task ${name} is declared twice`)
      tasks.set(name, parseInt(costStr, 10))
    } else if (directive === 'dep') {
      if (words.length < 3) fail(`error: line ${lineNo}: expected dep <name> <dependency>...`)
      const name = words[1]
      checkName(name, lineNo)
      const depNames = words.slice(2)
      for (const d of depNames) checkName(d, lineNo)
      depUsages.push({ name, depNames })
      if (!deps.has(name)) deps.set(name, new Set())
      const set = deps.get(name)
      for (const d of depNames) set.add(d)
    } else {
      fail(`error: line ${lineNo}: unknown directive ${directive}`)
    }
  }

  for (const usage of depUsages) {
    if (!tasks.has(usage.name)) fail(`error: unknown task ${usage.name}`)
    for (const d of usage.depNames) {
      if (!tasks.has(d)) fail(`error: unknown task ${d}`)
    }
  }

  return { tasks, deps }
}
