{"file_path":"src/graph.js","content":"export class CycleError extends Error {
  constructor(cyclePath) {
    super(`error: cycle: ${cyclePath.join(' -> ')}`)
    this.cyclePath = cyclePath
  }
}

function sortedDeps(name, deps) {
  const set = deps.get(name)
  if (!set) return []
  return Array.from(set).sort()
}

/**
 * Depth-first search from every task in ascending name order, walking each
 * task's dependencies in ascending name order. Throws CycleError describing
 * the first cycle found, as specified.
 */
export function detectCycle(tasks, deps) {
  const names = Array.from(tasks.keys()).sort()
  const state = new Map(names.map((n) => [n, 0])) // 0 unvisited, 1 visiting, 2 done
  const stack = []

  function visit(node) {
    state.set(node, 1)
    stack.push(node)
    for (const dep of sortedDeps(node, deps)) {
      const s = state.get(dep)
      if (s === 1) {
        const idx = stack.indexOf(dep)
        const cyclePath = stack.slice(idx).concat(dep)
        throw new CycleError(cyclePath)
      }
      if (s === 0) visit(dep)
    }
    state.set(node, 2)
    stack.pop()
  }

  for (const name of names) {
    if (state.get(name) === 0) visit(name)
  }
}

/**
 * Computes, for every task, its start time, finish time (unlimited workers)
 * and depth (wave number), following the dependency graph.
 */
export function computeTimings(tasks, deps) {
  const start = new Map()
  const finish = new Map()
  const depth = new Map()

  function compute(name) {
    if (finish.has(name)) return
    const depNames = deps.get(name)
    let maxFinish = 0
    let maxDepth = -1
    if (depNames) {
      for (const d of depNames) {
        compute(d)
        if (finish.get(d) > maxFinish) maxFinish = finish.get(d)
        if (depth.get(d) > maxDepth) maxDepth = depth.get(d)
      }
    }
    const s = maxFinish
    const f = s + tasks.get(name)
    start.set(name, s)
    finish.set(name, f)
    depth.set(name, maxDepth + 1)
  }

  for (const name of tasks.keys()) compute(name)

  return { start, finish, depth }
}
"}

{"file_path":"src/pack.js","content":"/**
 * Priority of each task is the cost of the longest chain that begins at it:
 * its own cost plus, recursively, the priority of the dependent with the
 * greatest priority (a dependent being a task that depends on this one).
 * A task nothing depends on is the end of its own chain.
 */
function computePriorities(tasks, deps) {
  const dependents = new Map()
  for (const name of tasks.keys()) dependents.set(name, [])
  for (const [name, depSet] of deps) {
    for (const d of depSet) {
      dependents.get(d).push(name)
    }
  }

  const priority = new Map()
  function compute(name) {
    if (priority.has(name)) return priority.get(name)
    let best = 0
    for (const dependent of dependents.get(name)) {
      const p = compute(dependent)
      if (p > best) best = p
    }
    const value = tasks.get(name) + best
    priority.set(name, value)
    return value
  }

  for (const name of tasks.keys()) compute(name)
  return priority
}

/**
 * Simulates the build graph on the given number of workers, returning
 * { workers: [{ runs: [{name, start, finish}] }], makespan }.
 */
export function packSchedule(tasks, deps, workerCount) {
  const priority = computePriorities(tasks, deps)
  const remaining = new Set(tasks.keys())
  const finishTime = new Map()
  const workers = Array.from({ length: workerCount }, () => ({ freeAt: 0, runs: [] }))

  let currentTime = 0
  while (remaining.size > 0) {
    let progressed = true
    while (progressed) {
      progressed = false

      let workerIdx = -1
      for (let i = 0; i < workerCount; i++) {
        if (workers[i].freeAt <= currentTime) {
          workerIdx = i
          break
        }
      }
      if (workerIdx === -1) break

      let best = null
      for (const name of remaining) {
        const depSet = deps.get(name)
        let ready = true
        if (depSet) {
          for (const d of depSet) {
            const f = finishTime.get(d)
            if (f === undefined || f > currentTime) {
              ready = false
              break
            }
          }
        }
        if (!ready) continue
        if (
          best === null ||
          priority.get(name) > priority.get(best) ||
          (priority.get(name) === priority.get(best) && name < best)
        ) {
          best = name
        }
      }
      if (best === null) break

      const start = currentTime
      const finish = start + tasks.get(best)
      workers[workerIdx].runs.push({ name: best, start, finish })
      workers[workerIdx].freeAt = finish
      finishTime.set(best, finish)
      remaining.delete(best)
      progressed = true
    }

    if (remaining.size === 0) break

    let next = Infinity
    for (const w of workers) {
      if (w.freeAt > currentTime && w.freeAt < next) next = w.freeAt
    }
    if (next === Infinity) break
    currentTime = next
  }

  let makespan = 0
  for (const f of finishTime.values()) if (f > makespan) makespan = f

  return { workers, makespan }
}
"}

